declare a clob;n number;begin
select count(*)into n from USER_OBJECTS where OBJECT_NAME='RRL_ASM_FINAL_SNAPSHOT';if n!=0 then raise_application_error(-20886,'ASM_FINAL_NAMESPACE_NOT_EMPTY');end if;
dbms_lob.createtemporary(a,true);for s in(select TEXT from USER_SOURCE where NAME='RRL_ASSEMBLY_SCALE_API'and TYPE='PACKAGE BODY'order by LINE)loop dbms_lob.append(a,replace(s.TEXT,chr(13),''));end loop;if rawtohex(sys.dbms_crypto.hash(a,sys.dbms_crypto.hash_sh256))!='445D03D595696D0EBDF6060008A5D050F66EEAEF9F0BE45F8E88E8D287226607'then raise_application_error(-20886,'ASM_FINAL_BEFORE_SOURCE_MISMATCH:RRL_ASSEMBLY_SCALE_API');end if;dbms_lob.freetemporary(a);
