dbms_lob.createtemporary(a,true);for s in(select TEXT from USER_SOURCE where NAME='RRL_WH_SCALE_API'and TYPE='PACKAGE BODY'order by LINE)loop dbms_lob.append(a,replace(s.TEXT,chr(13),''));end loop;if rawtohex(sys.dbms_crypto.hash(a,sys.dbms_crypto.hash_sh256))!='3D43A59F7BB7ECFF99E9E983BDE0708CC3707BD42BD0B7AEB2BA2836D8E4072A'then raise_application_error(-20886,'ASM_FINAL_BEFORE_SOURCE_MISMATCH:RRL_WH_SCALE_API');end if;dbms_lob.freetemporary(a);
dbms_lob.createtemporary(a,true);for s in(select TEXT from USER_SOURCE where NAME='RRL_WH_FINAL_SCALE_ADMISSION'and TYPE='PACKAGE BODY'order by LINE)loop dbms_lob.append(a,replace(s.TEXT,chr(13),''));end loop;if rawtohex(sys.dbms_crypto.hash(a,sys.dbms_crypto.hash_sh256))!='BDD43BC5844DEFDFC51EBBFFA7C8D2E002A88434F355B5EFAF8CA55BDDD9794C'then raise_application_error(-20886,'ASM_FINAL_BEFORE_SOURCE_MISMATCH:RRL_WH_FINAL_SCALE_ADMISSION');end if;dbms_lob.freetemporary(a);
select count(*)into n from USER_OBJECTS where STATUS='INVALID';if n!=0 then raise_application_error(-20886,'ASM_FINAL_INVALID_BEFORE');end if;end;
